/**
 * Routes where the global context banner is hidden.
 * Logged-in workspace pages use WorkspacePageHeader locally for a consistent title strip.
 */
export const PAGE_BANNER_HIDDEN_ROUTES = new Set([
  '/',
  '/login',
  '/register',
  '/forgot-password',
  '/reset-password',
  '/privacy-policy',
  '/terms-of-service',
  '/help',
  '/about-us',
  '/insights',
  '/why-carbon-intelligence',
  '/pricing',
  '/admin/login',
  '/dashboard',
  '/msme-profile',
  '/operations',
  '/carbon-twin',
  '/document-upload',
  '/data',
  '/carbon-footprint',
  '/compliance',
  '/reporting',
  '/finance',
  '/carbon-savings',
]);

/** Workspace prefixes that use WorkspacePageHeader (or custom chrome) instead of the global banner. */
const PAGE_BANNER_HIDDEN_PREFIXES = [
  '/msme-profile',
  '/operations',
  '/carbon-footprint',
  '/compliance',
  '/emissions-reduction-targets',
  '/carbon-marketplace',
  '/carbon-savings',
  '/carbon-forecasting',
  '/ai-advisor',
  '/carbon-copilot',
  '/green-loans',
  '/incentives',
  '/gift-',
  '/adeetie',
  '/buyer-audit',
  '/billing',
  '/settings',
  '/information',
  '/data-privacy',
];

export function isPageBannerHidden(pathname: string): boolean {
  const path = pathname || '/';
  if (PAGE_BANNER_HIDDEN_ROUTES.has(path)) {
    return true;
  }
  return PAGE_BANNER_HIDDEN_PREFIXES.some((prefix) => path.startsWith(prefix));
}

function matchRoutePageEntry(pathname: string) {
  return ROUTE_PAGE_INFO_ENTRIES.find((entry) => entry.match.test(pathname));
}

export function resolvePageInfo(pathname: string): PageInfoConfig {
  const path = pathname || '/';
  return matchRoutePageEntry(path)?.config ?? DEFAULT_PAGE_INFO;
}

const DOC_TITLE_FALLBACK = 'Carbon Intelligence';

/**
 * Browser tab title: short primary label plus product suffix for wayfinding across many tabs.
 */
export function resolveDocumentTitle(pathname: string): string {
  const path = pathname || '/';
  const explicit = DOCUMENT_TITLE_BY_PATH[path];
  if (explicit) {
    return `${explicit} · ${DOC_TITLE_FALLBACK}`;
  }
  const matched = matchRoutePageEntry(path);
  const primary = matched ? matched.config.title : 'Page not found';
  return `${primary} · ${DOC_TITLE_FALLBACK}`;
}
