/** Finance-overview option ids that are public government programmes. Lender products are excluded. */
export const PUBLIC_SCHEME_OPTION_IDS = ['adeetie', 'pm_kusum'] as const;

type SchemeOption = {
  id?: string;
  isEligible?: boolean;
  status?: string;
};

export type PublicSchemeSummary = {
  eligibleCount: number;
  inProgressCount: number;
  headline: string;
};

const publicHeadline = (eligibleCount: number): string => (
  eligibleCount > 0
    ? `${eligibleCount} public programme${eligibleCount === 1 ? '' : 's'} to review. Apply on the official government sites.`
    : 'Set a carbon goal, then open ADEETIE, MSME ZED, and PM-KUSUM on their official sites.'
);

export function summarizePublicSchemes(payload?: {
  summary?: { eligibleCount?: number; inProgressCount?: number; headline?: string };
  options?: SchemeOption[];
} | null): PublicSchemeSummary | null {
  if (!payload?.summary && !Array.isArray(payload?.options)) {
    return null;
  }

  const options = payload?.options;
  if (!Array.isArray(options)) {
    return {
      eligibleCount: Number(payload?.summary?.eligibleCount ?? 0),
      inProgressCount: Number(payload?.summary?.inProgressCount ?? 0),
      headline: payload?.summary?.headline || publicHeadline(Number(payload?.summary?.eligibleCount ?? 0)),
    };
  }

  const schemes = options.filter((option) =>
    PUBLIC_SCHEME_OPTION_IDS.includes(option.id as (typeof PUBLIC_SCHEME_OPTION_IDS)[number])
  );
  const eligibleCount = schemes.filter((option) => option.isEligible).length;
  const inProgressCount = schemes.filter(
    (option) => !option.isEligible && option.status === 'in_progress'
  ).length;

  return {
    eligibleCount,
    inProgressCount,
    headline: publicHeadline(eligibleCount),
  };
}
