export const normalizeComplianceSectionId = (
  section: string | null | undefined,
  validSections: readonly string[]
): string | null => {
  const trimmed = section?.trim();
  if (!trimmed) {
    return null;
  }
  if (validSections.includes(trimmed)) {
    return trimmed;
  }
  const alias = COMPLIANCE_SECTION_ALIASES[trimmed.toLowerCase()];
  if (alias && validSections.includes(alias)) {
    return alias;
  }
  return null;
};

export const flattenComplianceSections = (
  groups: readonly ComplianceSectionGroup[]
): ComplianceSectionDef[] => groups.flatMap((group) => group.sections);

export const complianceSectionHref = (
  trackPath: ComplianceTrackPath,
  sectionId: string
): string => {
  if (!sectionId || sectionId === 'overview') {
    return trackPath;
  }
  return `${trackPath}?section=${encodeURIComponent(sectionId)}`;
};

export const findComplianceSectionGroup = (
  groups: readonly ComplianceSectionGroup[],
  sectionId: string
): ComplianceSectionGroup | undefined =>
  groups.find((group) => group.sections.some((section) => section.id === sectionId));

