import React from 'react';
import { Box, Typography } from '@mui/material';
import { useNavigate } from 'react-router-dom';
import { isBillUploadEnabled } from '../../constants/uiVisibility';

type WorkflowStep = {
  step: string;
  title: string;
  detail: string;
  path: string;
};

const workflowSteps = (): WorkflowStep[] => {
  const bills = isBillUploadEnabled();
  return [
    {
      step: '1',
      title: 'My company',
      detail: 'Confirm the company, then map how the plant uses energy and materials.',
      path: '/msme-profile',
    },
    {
      step: '2',
      title: 'Data',
      detail: bills
        ? 'Upload electricity, fuel, and purchase bills, or connect your accounts.'
        : 'Connect your accounts so activity reaches the footprint.',
      path: bills ? '/document-upload' : '/data?section=connectors',
    },
    {
      step: '3',
      title: 'Carbon footprint',
      detail: 'See Scope 1–3, the hotspots, and the reduction ideas.',
      path: '/carbon-footprint?section=overview',
    },
    {
      step: '4',
      title: 'Compliance',
      detail: 'Prepare one disclosure report: BRSR, ISO 14064, or CBAM.',
      path: '/compliance',
    },
    {
      step: '5',
      title: 'Carbon goal',
      detail: 'Set this year’s cut, then open the official government scheme sites.',
      path: '/emissions-reduction-targets',
    },
    {
      step: '6',
      title: 'Offsets',
      detail: 'Buy or retire credits after the footprint is measured.',
      path: '/carbon-marketplace',
    },
  ];
};

const DashboardWorkflowGuide: React.FC = () => {
  const navigate = useNavigate();
  const steps = workflowSteps();

  return (
    <Box component="section" aria-label="How this workspace works" sx={{ mb: 3 }}>
      <Typography variant="subtitle1" sx={{ fontWeight: 700, mb: 0.5 }}>
        How this workspace works
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 1.5, maxWidth: 720 }}>
        Work through these six steps. Each one opens the same page as the left menu.
        {' '}
        <Box
          component="button"
          type="button"
          onClick={() => navigate('/ai-advisor')}
          sx={{
            p: 0,
            border: 0,
            bgcolor: 'transparent',
            color: 'primary.main',
            font: 'inherit',
            cursor: 'pointer',
            textDecoration: 'underline',
          }}
        >
          AI Advisor
        </Box>
        {' '}
        answers questions about your footprint, water, solar, and how to cut.
      </Typography>
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr', lg: 'repeat(3, 1fr)' },
          gap: 1.25,
        }}
      >
        {steps.map((step) => (
          <Box
            key={step.step}
            component="button"
            type="button"
            onClick={() => navigate(step.path)}
            sx={{
              display: 'flex',
              gap: 1.25,
              textAlign: 'left',
              p: 1.5,
              border: 1,
              borderColor: 'divider',
              borderRadius: 2,
              bgcolor: 'background.paper',
              cursor: 'pointer',
              '&:hover': { borderColor: 'primary.main' },
            }}
          >
            <Typography
              variant="subtitle2"
              color="primary"
              sx={{ fontWeight: 800, minWidth: 16, lineHeight: 1.4 }}
            >
              {step.step}
            </Typography>
            <Box>
              <Typography variant="body2" sx={{ fontWeight: 700, lineHeight: 1.4 }}>
                {step.title}
              </Typography>
              <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.25, lineHeight: 1.45 }}>
                {step.detail}
              </Typography>
            </Box>
          </Box>
        ))}
      </Box>
    </Box>
  );
};

export default DashboardWorkflowGuide;
