import React from 'react';
import {
  Box,
  Card,
  CardActionArea,
  Grid,
  Stack,
  Typography,
} from '@mui/material';
import {
  AccountBalanceWallet as SavingsIcon,
  Co2 as Co2Icon,
  EmojiEvents as ScoreIcon,
  Forest as TreesIcon,
  Nature as EcoIcon,
  Savings as ReductionIcon,
  Spa as CreditsIcon,
  TrendingDown as EmissionsIcon,
} from '@mui/icons-material';
import { alpha, useTheme } from '@mui/material/styles';
import { useNavigate } from 'react-router-dom';
import { formatInr } from '../../constants/pricingPlans';

export interface DashboardMetricsGridProps {
  carbonScore: number;
  scoreLabel: string;
  scoreColor: 'success' | 'warning' | 'error' | 'default';
  carbonEmissionsKg: number;
  totalCo2SavedKg: number;
  periodCo2SavedKg: number;
  savingsPercentage: number;
  costSavingsInr: number;
  treesEquivalent: number;
  greenCreditsAvailable?: number;
  forecastTCO2e?: number;
  onNavigate?: (path: string) => void;
}

interface MetricTileConfig {
  id: string;
  title: string;
  value: string;
  unit?: string;
  subtitle: string;
  accent: string;
  icon: React.ReactNode;
  path?: string;
}

function formatCompactNumber(value: number, decimals = 1): string {
  if (!Number.isFinite(value) || value <= 0) return '0';
  if (value >= 1_000_000) return `${(value / 1_000_000).toFixed(decimals)}M`;
  if (value >= 1_000) return `${(value / 1_000).toFixed(decimals)}K`;
  return value % 1 === 0 ? String(Math.round(value)) : value.toFixed(decimals);
}

function MetricTile({
  tile,
  onNavigate,
}: {
  tile: MetricTileConfig;
  onNavigate?: (path: string) => void;
}) {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  const inner = (
    <>
      <Box
        sx={{
          height: 4,
          background: `linear-gradient(90deg, ${tile.accent}, ${alpha(tile.accent, 0.55)})`,
        }}
      />
      <Box sx={{ p: 2 }}>
        <Stack direction="row" alignItems="flex-start" justifyContent="space-between" spacing={1}>
          <Box
            sx={{
              width: 40,
              height: 40,
              borderRadius: 2,
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              bgcolor: alpha(tile.accent, isDark ? 0.22 : 0.14),
              color: tile.accent,
            }}
          >
            {tile.icon}
          </Box>
        </Stack>
        <Typography
          variant="h4"
          sx={{
            fontWeight: 800,
            letterSpacing: '-0.03em',
            lineHeight: 1.1,
            mt: 1.25,
            color: tile.accent,
          }}
        >
          {tile.value}
          {tile.unit ? (
            <Typography
              component="span"
              variant="body2"
              sx={{ ml: 0.75, fontWeight: 600, color: 'text.secondary', verticalAlign: 'middle' }}
            >
              {tile.unit}
            </Typography>
          ) : null}
        </Typography>
        <Typography variant="subtitle2" sx={{ fontWeight: 700, mt: 0.75 }}>
          {tile.title}
        </Typography>
        <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.35, lineHeight: 1.45 }}>
          {tile.subtitle}
        </Typography>
      </Box>
    </>
  );

  return (
    <Card
      variant="outlined"
      sx={{
        height: '100%',
        minHeight: 168,
        borderColor: alpha(tile.accent, isDark ? 0.4 : 0.28),
        background: isDark
          ? `linear-gradient(160deg, ${alpha(tile.accent, 0.14)} 0%, ${theme.palette.background.paper} 72%)`
          : `linear-gradient(160deg, ${alpha(tile.accent, 0.1)} 0%, ${theme.palette.background.paper} 78%)`,
        transition: 'transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease',
        ...(tile.path
          ? {
              '&:hover': {
                transform: 'translateY(-3px)',
                boxShadow: theme.shadows[6],
                borderColor: alpha(tile.accent, isDark ? 0.55 : 0.45),
              },
            }
          : {}),
      }}
    >
      {tile.path && onNavigate ? (
        <CardActionArea onClick={() => onNavigate(tile.path!)} sx={{ height: '100%' }}>
          {inner}
        </CardActionArea>
      ) : (
        inner
      )}
    </Card>
  );
}

export const DashboardMetricsGrid: React.FC<DashboardMetricsGridProps> = ({
  carbonScore,
  scoreLabel,
  scoreColor,
  carbonEmissionsKg,
  totalCo2SavedKg,
  periodCo2SavedKg,
  savingsPercentage,
  costSavingsInr,
  treesEquivalent,
  greenCreditsAvailable = 0,
  forecastTCO2e = 0,
  onNavigate,
}) => {
  const theme = useTheme();
  const navigate = useNavigate();
  const handleNavigate = onNavigate ?? ((path: string) => navigate(path));

  const paletteKey = scoreColor === 'default' ? 'primary' : scoreColor;
  const scoreAccent = theme.palette[paletteKey].main;
  const footprintT = carbonEmissionsKg > 0 ? (carbonEmissionsKg / 1000).toFixed(2) : '—';
  const hasFootprint = carbonEmissionsKg > 0;
  const hasScore = carbonScore > 0;

  const tiles: MetricTileConfig[] = [
    {
      id: 'score',
      title: 'Carbon score',
      value: hasScore ? String(Math.round(carbonScore)) : '—',
      unit: '/ 100',
      subtitle: hasScore
        ? scoreLabel
        : hasFootprint
          ? scoreLabel
          : 'Run assessment to calculate score',
      accent: scoreAccent,
      icon: <ScoreIcon fontSize="small" />,
      path: '/carbon-footprint',
    },
    {
      id: 'emissions',
      title: 'CO₂ emissions',
      value: footprintT,
      unit: 'tCO₂e',
      subtitle: hasFootprint
        ? `${formatCompactNumber(carbonEmissionsKg)} kg from latest assessment`
        : 'Run assessment to measure footprint',
      accent: theme.palette.error.main,
      icon: <EmissionsIcon fontSize="small" />,
      path: '/carbon-footprint',
    },
    {
      id: 'saved',
      title: 'CO₂ saved',
      value: formatCompactNumber(totalCo2SavedKg),
      unit: 'kg',
      subtitle:
        periodCo2SavedKg > 0
          ? `${formatCompactNumber(periodCo2SavedKg)} kg saved this period`
          : 'Track reductions as you implement actions',
      accent: theme.palette.success.main,
      icon: <Co2Icon fontSize="small" />,
      path: '/carbon-savings',
    },
    {
      id: 'rupees',
      title: 'Savings in rupees',
      value: costSavingsInr > 0 ? formatInr(costSavingsInr) : '₹0',
      subtitle: 'Estimated operational value from CO₂ reductions',
      accent: theme.palette.warning.dark,
      icon: <SavingsIcon fontSize="small" />,
      path: '/carbon-savings',
    },
    {
      id: 'trees',
      title: 'Trees equivalent',
      value: treesEquivalent > 0 ? String(treesEquivalent) : '0',
      unit: treesEquivalent === 1 ? 'tree-year' : 'tree-years',
      subtitle: 'Illustrative CO₂ absorption equivalent',
      accent: '#2e7d32',
      icon: <TreesIcon fontSize="small" />,
      path: '/carbon-savings',
    },
    {
      id: 'reduction',
      title: 'Reduction achieved',
      value: savingsPercentage > 0 ? savingsPercentage.toFixed(1) : '0',
      unit: '%',
      subtitle: 'Versus your previous assessment baseline',
      accent: theme.palette.info.main,
      icon: <ReductionIcon fontSize="small" />,
      path: '/carbon-savings',
    },
    {
      id: 'credits',
      title: 'Green credits',
      value: String(Math.round(greenCreditsAvailable)),
      unit: 'available',
      subtitle: greenCreditsAvailable > 0 ? 'Ready to allocate or retire' : 'Earn credits through sustainability actions',
      accent: theme.palette.secondary.main,
      icon: <CreditsIcon fontSize="small" />,
      path: '/carbon-marketplace?tab=1',
    },
    {
      id: 'outlook',
      title: 'Emissions outlook',
      value: forecastTCO2e > 0 ? forecastTCO2e.toFixed(2) : '—',
      unit: forecastTCO2e > 0 ? 'tCO₂e' : undefined,
      subtitle: forecastTCO2e > 0 ? 'Modelled forward footprint' : 'Forecast appears after baseline data',
      accent: theme.palette.primary.dark,
      icon: <EcoIcon fontSize="small" />,
      path: '/carbon-forecasting',
    },
  ];

  return (
    <Box sx={{ mb: 0 }}>
      <Typography variant="overline" color="primary" sx={{ fontWeight: 800, letterSpacing: '0.1em' }}>
        At a glance
      </Typography>
      <Typography variant="h6" sx={{ fontWeight: 800, letterSpacing: '-0.02em', mb: 0.5 }}>
        Your sustainability snapshot
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2, maxWidth: 720, lineHeight: 1.6 }}>
        Key carbon performance indicators — tap a card for details.
      </Typography>
      <Grid container spacing={2}>
        {tiles.map((tile) => (
          <Grid item xs={6} sm={4} md={3} key={tile.id}>
            <MetricTile tile={tile} onNavigate={handleNavigate} />
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};
